public record Interval(int startInclusive, int endExclusive) {
    public boolean contains(int value) {
        return value >= startInclusive && value < endExclusive;
    }
}

import java.util.List;
public record Names(List<String> values) {
    public Names {
        values = List.copyOf(values);
    }
}

import java.math.BigDecimal;
import java.util.Objects;
public record Amount(BigDecimal value) {
    public Amount {
        Objects.requireNonNull(value);
    }
}

import java.math.BigDecimal;
import java.util.Objects;
public record Quote(BigDecimal value) {
    public Quote {
        Objects.requireNonNull(value);
    }
}

import kotlin.contracts.ExperimentalContracts
import kotlin.contracts.contract

@OptIn(ExperimentalContracts::class)
fun ensureName(value: String?) {
    contract { returns() implies (value != null) }
}

public final class Ports {
    public static int validate(int port) {
        assert port >= 1 && port <= 65535;
        return port;
    }
}

class EndpointBuilder {
    var port: Int = 443
        private set

    fun port(port: Int): EndpointBuilder {
        this.port = port
        require(port in 1..65535) { "unexpected port: $port" }
        return this
    }
}

fun submit(payload: String) {
    try {
        client.post(payload)
    } catch (failure: java.io.IOException) {
        client.post(payload)
    }
}

fun readLine(source: okio.BufferedSource): String =
    try {
        source.readUtf8LineStrict(4)
    } catch (failure: java.io.EOFException) {
        source.readUtf8LineStrict(5)
    }

fun charge() {
    state.update { previous ->
        gateway.charge()
        previous.copy(charges = previous.charges + 1)
    }
}

@Transactional
public void register(String name) {
    if (repository.activeNameCount(name) == 0) {
        repository.insert(name);
    }
}

data class Request(@field:jakarta.validation.constraints.NotBlank val name: String)

@RestController
class CreateController(private val service: Service) {
    @PostMapping("/items")
    fun create(@RequestBody @jakarta.validation.Valid request: Request) {
        service.create(request)
    }
}
